const D=window.SENATE_DATA;
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=(v,compact=false)=>v==null?'Not collected':compact?(Math.abs(v)>=1e6?'$'+num(v/1e6,2)+'m':'$'+num(v/1e3,0)+'k'):'$'+num(v,0);
