const short=(s,n=100)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':String(s||'');
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const initials=s=>String(s||'').split(' ').filter(Boolean).filter(x=>x.length>2).map(x=>x[0]).slice(0,2).join('');
const indexed=rows=>Object.fromEntries((rows||[]).map(x=>[x.district??x.id,x]));
const E=indexed(D.elections.districts),G=indexed(D.geometry.districts),F=indexed(D.finance.districts),C=indexed(D.census.districts),R=indexed(D.research.districts),O=indexed((D.overlays.districts||[]).filter(x=>x.detailedPath)),DIR=indexed(D.directory.districts);
