const profileFor=(id,name)=>{const p=profiles.find(x=>x.district===Number(id));if(!p||!name)return p;const ballot=E[id]?.candidates.find(c=>norm(c.name)===norm(name));return norm(p.name)===norm(name)||(ballot?.incumbent&&!/incoming/i.test(p.profileStatus))?p:null;};
const metrics=(id)=>Object.fromEntries((C[id]?.metrics||[]).map(x=>[x.key,x]));
