const state={route:'home',district:44,tab:'overview',issue:1,heat:'silver',mode:'3D',compareA:38,compareB:39,peopleGroup:'race',filterDistrict:0,filterEvidence:'all',filterCandidate:'all',search:'',layer:0,pdfPage:1,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,geo:'neighborhoods',financeView:'donors',mediaPlatform:'all',sourceTab:'registry',migrationTab:'fresh',peopleTab:'census'};
