const mainNav=[['home','Command Center'],['atlas','3D Senate Map'],['districts','District Dossiers'],['candidates','Candidate Profiles'],['issues','Issue Timelines'],['compare','Comparison Mode'],['alerts','Change Alerts'],['sources','Source Registry'],['exports','Export Briefs']];
