function navHTML(rows){return rows.map(([id,title])=>`<button class="nav-item ${state.route===id?'active':''}" data-nav="${id}" title="${title}" ${state.route===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${title}</span>${id==='alerts'?'<span class="nav-count">4</span>':''}</button>`).join('');}
function districtOptions(current,all=false){return (all?'<option value="0">All 63 districts</option>':'')+Object.values(E).map(x=>`<option value="${x.district}" ${Number(current)===x.district?'selected':''}>SD ${String(x.district).padStart(2,'0')} · ${esc(x.leadingCandidate)}</option>`).join('');}
function sourceNote(text){return `<div class="data-note">${text}</div>`;}
function gap(text){return `<div class="data-gap"><span class="tag dark">Collection gap</span><p>${esc(text)}</p></div>`;}
function table(headers,rows){return `<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function stat(value,label,sub=''){return `<div class="stat-card"><span>${esc(label)}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function heading(title,kicker,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(kicker)}</span><h2 class="metallic">${esc(title)}</h2><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
