function candidateCards(id,compact=true){return E[id].candidates.map((c,i)=>`<button class="candidate-card ${i===0?'leading':''}" data-candidate="${esc(c.name)}" data-id="${id}">${avatar(id,c.name)}<span class="candidate-info"><strong>${esc(c.name)}</strong><small>${esc(c.party)} ${c.incumbent?'· Incumbent':'· Challenger'}<br>${esc(c.resultStatus)}</small></span><span class="candidate-votes">${num(c.shareOfValidVotes,1)}<small>% valid votes</small></span></button>`).join('');}
function historyLines(id){const e=E[id];return [{year:'2026',c:e.candidates,status:'Unofficial'},{year:'2024',c:e.history2024?.candidates||[],status:'Certified'}].map(row=>`<div class="history-line"><div class="history-label"><b>${row.year}</b><span>${row.status}</span></div>${row.c.slice(0,2).map((c,i)=>`<div class="result-track" title="${esc(c.name)} · ${pct(c.shareOfValidVotes)}"><span style="width:${c.shareOfValidVotes||0}%;background:${i===0?'linear-gradient(90deg,#d2bc82,#87703f)':'linear-gradient(90deg,#90999d,#535b5e)'}"></span><em>${esc(c.name.split(' ').at(-1))} ${pct(c.shareOfValidVotes)}</em></div>`).join('')}</div>`).join('');}
function sourceRow(u,title,note){return `<a class="source-row" href="${esc(safeURL(u))}"><span>▧</span><div><strong>${esc(title)}</strong><small>${esc(note)}</small></div><b>↗</b></a>`;}
function districtIssues(id){return issues.filter(x=>districtEvidence(id).some(r=>(r.issueIds||[]).includes(Number(x.id)))||R[id]?.issues?.some(r=>r.id===x.id));}
function sideDossier(){const id=state.district,e=E[id],ci=districtIssues(id);return `<div class="dossier-scroll"><div class="dossier-title"><div class="district-heading"><h2>SD ${String(id).padStart(2,'0')}</h2><span class="tag">${e.unopposedOnPrintedBallot?'UNOPPOSED':e.leadPercentagePoints<5?'CLOSE CONTEST':'DISTRICT DOSSIER'}</span></div><p>${esc(region(id))}</p><small>${e.electionDistrictsTotal?`${num(e.electionDistrictsReporting)} / ${num(e.electionDistrictsTotal)} reporting EDs`:'Reporting-ED count unavailable'} · BOE 21 Nov 2026</small></div><div class="dossier-section-title">2026 CANDIDATES <span>UNOFFICIAL RETURNS</span></div><div class="candidate-list">${candidateCards(id)}</div><div class="dossier-section-title">ELECTORAL HISTORY <button data-tab="elections" data-open-dossier="1">View ›</button></div><div class="history-lines">${historyLines(id)}</div><div class="dossier-section-title">DISTRICT ISSUE RECORDS <span>${ci.length} TOPICS</span></div><div class="issue-chips">${ci.slice(0,6).map(x=>`<button class="issue-chip" data-issue="${x.id}" data-issue-district="${id}">${esc(short(x.title,29))}</button>`).join('')||'<span class="muted">No linked evidence collected.</span>'}</div><div class="dossier-section-title">SOURCE & EVIDENCE</div><div class="source-stack">${sourceRow(e.sourceUrl,'NYS Board of Elections','21 Nov 2026 · unofficial returns')}${sourceRow(D.finance.meta.sourceUrl,'Campaign finance disclosures',`${F[id]?.coveredCandidates||0} candidates covered · 22 Nov`)}${sourceRow(C[id]?.metrics?.[0]?.officialSourceUrl,'Census district profile','ACS 2020–24 · retrieved 23 Nov')}</div><div class="dossier-actions"><button class="primary" data-open-dossier="1">Open full dossier →</button><button class="outline small" data-export-district="${id}">↓ Brief</button></div><div class="panel-foot">Serving member: ${esc(e.incumbent?.name||'Vacant')}. Election returns and office-holding are separate records.</div></div>`;}
function heatColor(id){const e=E[id];if(state.heat==='silver')return id===state.district?'#d6b468':'#80888c';if(state.heat==='margin'&&e.leadPercentagePoints==null)return '#465252';if(state.heat==='party')return e.leadingParty==='DEM'?'#7299b4':'#b37c6d';if(state.heat==='issues'){const n=issueEvidence(state.issue).filter(x=>x.district===id).length;return n?`hsl(43,${35+Math.min(n,4)*7}%,${32+Math.min(n,4)*9}%)`:'#363c40';}let value=state.heat==='margin'?Math.min(e.leadPercentagePoints,50)/50:state.heat==='income'?Math.min(metric(id,'median_household_income')||0,180000)/180000:state.heat==='rent'?(metric(id,'renter_share_pct')||0)/100:Math.min(F[id]?.totalContributions||0,4000000)/4000000;return `hsl(${44-value*9},${15+value*40}%,${24+value*41}%)`;}
function svgMap({id='mapSvg',classes='map-svg',clickable=true,heat=true,viewBox='0 0 1000 780'}={}){return `<svg id="${id}" class="${classes}" viewBox="${viewBox}" aria-label="Official New York Senate district boundaries" role="group"><path d="${D.geometry.state.path}" fill="#101416" stroke="#b7b2a2" stroke-width="2"/>${D.geometry.districts.map(g=>`<path class="senate-shape ${g.id===state.district?'selected':''}" data-map-district="${g.id}" ${clickable?`tabindex="0" role="button" aria-label="Open Senate District ${g.id}"`:''} d="${g.path}" fill="${heat?heatColor(g.id):'#6f777a'}" stroke="${g.id===state.district?'#ffe4a1':'#d4d8d4'}" stroke-width="${g.id===state.district?'2.6':'.8'}" vector-effect="non-scaling-stroke"><title>SD ${g.id} · ${esc(E[g.id]?.leadingCandidate)} · ${num(E[g.id]?.leadPercentagePoints,2)} pt lead</title></path>`).join('')}${D.geometry.places.filter(x=>!['Lake Ontario','Adirondacks','Long Island'].includes(x.name)).map(p=>`<g pointer-events="none"><circle cx="${p.position[0]}" cy="${p.position[1]}" r="2.2" fill="#f1d69c"/><text x="${p.position[0]+7}" y="${p.position[1]-4}" fill="#e4e3db" font-family="Arial" font-size="12">${esc(p.name)}</text></g>`).join('')}</svg>`;}
function mapHUD(){return `<div class="atlas-title"><h2>NYS Senate — District Atlas <span>(63 seats)</span></h2><p>OFFICIAL DISTRICT GEOGRAPHY · SELECT A SEAT TO OPEN ITS DOSSIER</p></div><div class="map-hud"><div class="glass-card seat-control"><span class="small-title">SENATE ELECTION 2026</span><div class="seat-numbers"><span><strong>${Object.values(E).filter(x=>x.leadingParty==='DEM').length}</strong><small>DEM LEADS</small></span><i>/</i><span><strong>${Object.values(E).filter(x=>x.leadingParty==='REP').length}</strong><small>REP LEADS</small></span></div><div class="control-bar"><i style="width:76.19%"></i></div><p>Unofficial · BOE 21 November</p></div><div class="glass-card heat-control"><label class="small-title" for="heatSelect">HEATMAP LAYER</label><select id="heatSelect">${[['silver','District atlas'],['margin','2026 leading margin'],['party','2026 leading party'],['money','Disclosed contributions'],['income','Median household income'],['rent','Renter households'],['issues','Selected issue evidence']].map(([v,l])=>`<option value="${v}" ${state.heat===v?'selected':''}>${l}</option>`).join('')}</select><select id="mapIssue" aria-label="Heatmap issue" ${state.heat==='issues'?'':'hidden'}>${issues.map(x=>`<option value="${x.id}" ${x.id===state.issue?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div class="heat-ramp"></div><div class="heat-labels"><span id="heatLow">Lower</span><span id="heatHigh">Higher</span></div><small id="heatNote">${heatNote()}</small></div></div><div class="map-tools"><div class="mode-segment"><button data-map-mode="3D" class="${state.mode==='3D'?'active':''}">3D</button><button data-map-mode="2D" class="${state.mode==='2D'?'active':''}">2D</button></div><button data-map-action="rotate" class="map-control" title="Rotate the atlas">⟳ Rotate</button><div class="zoom-tools"><button data-map-action="in" aria-label="Zoom in">＋</button><button data-map-action="out" aria-label="Zoom out">−</button><button data-map-action="reset" aria-label="Reset state view">⌂</button></div><button data-map-action="nyc" class="map-control">NYC</button><button data-map-action="longIsland" class="map-control">Long Island</button></div><div class="map-caption">NYS GIS boundaries · 2022 Senate plan<br><span id="mapModeCaption">${state.mode==='3D'?'Raised district geography · drag to pan, Shift-drag to rotate':'2D atlas · select any district'}</span></div><div class="map-tip" id="mapTip" hidden></div>`;}
function heatNote(){return {silver:'Click a district · gold marks selection',margin:'Lead in percentage points of valid votes',party:'Blue: DEM lead · copper: REP lead',money:'2025–26 gross disclosed donations; coverage varies',income:'ACS 2020–24 household estimate',rent:'ACS 2020–24 occupied households',issues:'Count of collected records; not public opinion'}[state.heat];}
function timelineSVG(id=null){let data=sources.filter(s=>!id||districtEvidence(id).some(r=>(r.sourceIds||[]).includes(s.id)));let counts=[0,0,0,0,0,0];for(const s of data){let d=new Date(s.publishedAt||'');if(!Number.isNaN(+d)&&d.getUTCFullYear()===2026){let m=d.getUTCMonth();if(m>=5&&m<=10)counts[m-5]++;}}const max=Math.max(1,...counts),points=counts.map((v,i)=>`${20+i*54},${105-v/max*77}`);return `<svg class="chart-svg" viewBox="0 0 320 138" role="img" aria-label="Source publication counts June through November 2026"><defs><linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#cfb268" stop-opacity=".27"/><stop offset="1" stop-color="#cfb268" stop-opacity="0"/></linearGradient></defs>${[30,65,105].map(y=>`<path class="gridline" d="M18 ${y}H307"/>`).join('')}<path class="area" fill="url(#areaGrad)" d="M20 105 L${points.join(' L')} L290 105Z"/><polyline class="chartline" points="${points.join(' ')}" fill="none" stroke="#d1b572" stroke-width="2"/>${counts.map((v,i)=>`<circle cx="${20+i*54}" cy="${105-v/max*77}" r="3" fill="#ead39c"><title>${v} dated source records</title></circle><text x="${20+i*54}" y="127" text-anchor="middle" fill="#a5a9a6" font-size="9">${['JUN','JUL','AUG','SEP','OCT','NOV'][i]}</text>`).join('')}<text x="20" y="15" fill="#b7bdb7" font-size="9">DATED RESEARCH SOURCES · 2026</text></svg>`;}
function home(){const e=E[state.district];return `<div class="command-grid route-enter"><section class="panel atlas-panel"><div class="map-stage" id="mapStage">${svgMap()}<div class="map-webgl" id="mapWebgl"></div><div class="map-labels" id="mapLabels"></div>${mapHUD()}</div><div class="state-strip"><button data-nav="districts"><strong>63</strong><small>SENATE DISTRICTS</small></button><button data-nav="candidates"><strong>112</strong><small>GENERAL CANDIDATES</small></button><button data-nav="issues"><strong>20</strong><small>ISSUE TRACKS</small></button><button data-nav="money"><strong>103<em>/112</em></strong><small>FINANCE COVERAGE</small></button><button data-nav="layers"><strong>24</strong><small>RESEARCH LAYERS</small></button></div></section><aside class="panel dossier-panel" id="sideDossier" aria-label="Selected district dossier">${sideDossier()}</aside><div class="bottom-grid"><section class="panel"><div class="panel-heading"><h3>Change Alerts</h3><span class="tag dark">4</span></div><div class="panel-body"><button class="event-item" data-nav="people"><span class="event-icon">◎</span><span><b>Demographic collection updated</b><p>38 Census tables · all 63 districts</p><small>23 NOV · ACS 2020–24</small></span></button><button class="event-item" data-district="43"><span class="event-icon">△</span><span><b>SD 43 · 340-vote lead</b><p>Close unofficial contest · inspect returns</p><small>BOE SNAPSHOT · 21 NOV</small></span></button><button class="event-item" data-nav="money"><span class="event-icon">◇</span><span><b>Campaign disclosures collected</b><p>103 candidate records with contributions</p><small>22 NOV · OFFICIAL FILINGS</small></span></button></div><button class="panel-foot" data-nav="alerts">Open the collection and change log →</button></section><section class="panel"><div class="panel-heading"><h3>Issue Timeline</h3><button data-nav="issues" class="meta">20 ISSUES ›</button></div><div class="panel-body">${timelineSVG()}<div class="mini-table">${districtIssues(state.district).slice(0,2).map(x=>`<button data-issue="${x.id}" data-issue-district="${state.district}"><b>${esc(short(x.title,35))}</b><span>${issueEvidence(x.id).length} records ›</span></button>`).join('')}</div></div><div class="panel-foot">Source activity, not polling or measured voter salience.</div></section><section class="panel compare-mini"><div class="panel-heading"><h3>Comparison Mode</h3><button data-nav="compare" class="meta">OPEN ›</button></div><div class="panel-body"><div class="comparison-title"><b>SD ${state.compareA}</b><span>VS</span><b>SD ${state.compareB}</b></div>${miniComparison()}<button class="outline small" data-nav="compare">Open comparison →</button></div><div class="panel-foot">Same definitions · visible source periods</div></section></div></div>`;}
function miniComparison(){return `<div class="mini-table">${[['2026 lead',num(E[state.compareA].leadPercentagePoints,2)+' pt',num(E[state.compareB].leadPercentagePoints,2)+' pt'],['Median income',money(metric(state.compareA,'median_household_income'),true),money(metric(state.compareB,'median_household_income'),true)],['Renters',pct(metric(state.compareA,'renter_share_pct')),pct(metric(state.compareB,'renter_share_pct'))]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span><strong>${x[2]}</strong></div>`).join('')}</div>`;}
function updateSelection(id){if(!E[id])return;state.district=Number(id);atlas?.select(state.district);if(state.route==='home'||state.route==='atlas'){$('#sideDossier').innerHTML=sideDossier();$$('.senate-shape').forEach(p=>{p.classList.toggle('selected',+p.dataset.mapDistrict===state.district);p.setAttribute('fill',heatColor(+p.dataset.mapDistrict));});bindImages();}else render();updateHash();}
async function initAtlas(){const epoch=renderEpoch,el=$('#mapWebgl');if(!el)return;const options={selected:state.district,onSelect:updateSelection,onHover:mapHover,colorFor:heatColor,labelsContainer:$('#mapLabels'),motion:state.motion};try{atlas=createAtlas3D(el,D.geometry,options);}catch(err){console.info('Using the projected relief renderer for this browser.');el.replaceChildren();$('#mapLabels').replaceChildren();try{atlas=createAtlasSVG(el,D.geometry,options);}catch(fallbackError){console.warn('Using the flat official atlas.',fallbackError);state.mode='2D';}}if(epoch!==renderEpoch){atlas?.dispose();return;}setMapMode(state.mode);}

function mapHover(id,pos){const tip=$('#mapTip');if(!tip)return;if(!id){tip.hidden=true;return;}const e=E[id];tip.hidden=false;tip.innerHTML=`<b>SD ${id} · ${esc(e.leadingCandidate)}</b><span>${esc(e.leadingParty)} lead · ${num(e.leadPercentagePoints,2)} pt · unofficial</span>`;if(pos){const rect=$('#mapStage').getBoundingClientRect();tip.style.left=Math.max(8,Math.min((pos.clientX??pos.x)-rect.left+10,rect.width-240))+'px';tip.style.top=Math.max(40,(pos.clientY??pos.y)-rect.top-55)+'px';}}
function setMapMode(mode){state.mode=mode;const flat=$('#mapSvg'),web=$('#mapWebgl'),labels=$('#mapLabels');if(flat)flat.style.visibility=mode==='3D'&&atlas?'hidden':'visible';if(web)web.hidden=mode==='2D';if(labels)labels.hidden=mode==='2D';$$('[data-map-mode]').forEach(x=>x.classList.toggle('active',x.dataset.mapMode===mode));if($('#mapModeCaption'))$('#mapModeCaption').textContent=mode==='3D'?'Raised district geography · drag to pan, Shift-drag to rotate':'2D atlas · select any district';}
function paddedBounds(b,p=.08){let [x,y,w,h]=b;if(w>x&&h>y&&w>1000){w-=x;h-=y;}const m=Math.max(w,h)*p;return `${x-m} ${y-m} ${w+2*m} ${h+2*m}`;}
function districtMap(id,detail=true){const g=G[id],ov=O[id],use=detail&&ov,features=use?(state.geo==='none'?[]:state.geo==='electionDistricts'?ov.electionDistricts:ov.neighborhoods):[];const b=use?ov.detailedBounds:g.bounds;return `<svg class="district-svg" viewBox="${paddedBounds(b,.09)}" aria-label="SD ${id} ${use?esc(ov.detailedBoundaryScope):'official boundary'}"><defs><linearGradient id="districtFill"><stop stop-color="#a88e50"/><stop offset="1" stop-color="#4c4431"/></linearGradient></defs><path class="geo-main" d="${use?ov.detailedPath:g.path}" fill="url(#districtFill)" stroke="#dfc88d" stroke-width="1.5" vector-effect="non-scaling-stroke"/>${(features||[]).map(x=>`<path class="geo-ed" data-geo-feature="${esc(x.id)}" d="${x.path}" fill="${state.geo==='electionDistricts'?'#8e825c18':'#c0b58325'}" stroke="#ded8c1" stroke-width="${state.geo==='electionDistricts'?'.4':'.7'}" vector-effect="non-scaling-stroke"><title>${esc(x.name)}${x.partial?' · partial intersection':''}</title></path>`).join('')}</svg>`;}
function districtGrid(){return heading('District dossiers','THE SIXTY-THREE','Every district has an independent evidence record. Open a seat to connect elections, people, money, policy and place.')+`<div class="workspace-body"><div class="workspace-toolbar"><input id="districtSearch" type="search" placeholder="Search district, county or candidate" value="${esc(state.search)}"><button class="outline small" data-sort="close">Closest contests first</button><button class="outline small" data-sort="number">District order</button></div><div class="district-grid" id="districtGrid">${districtTiles()}</div></div>`;}
let districtSort='number';
function districtTiles(){let rows=Object.values(E).filter(x=>`${x.district} ${region(x.district)} ${x.candidates.map(c=>c.name).join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));if(districtSort==='close')rows.sort((a,b)=>(a.leadPercentagePoints??999)-(b.leadPercentagePoints??999));return rows.map(e=>`<button class="district-tile" data-open-district="${e.district}"><div><b>SD ${String(e.district).padStart(2,'0')}</b><span class="tag dark">${e.leadingParty}</span></div><svg viewBox="${paddedBounds(G[e.district].bounds,.1)}"><path d="${G[e.district].path}" fill="#8e815d" stroke="#e2cc93" stroke-width="1" vector-effect="non-scaling-stroke"/></svg><h3>${esc(e.leadingCandidate)}</h3><p>${esc(short(region(e.district),42))}</p><small>${e.unopposedOnPrintedBallot?'Unopposed on printed ballot':num(e.leadPercentagePoints,2)+' pt lead · unofficial'}</small></button>`).join('')||'<p class="empty-search">No matching district.</p>';}
const dossierTabs=[['overview','Overview'],['elections','Elections'],['money','Money'],['issues','Issues'],['people','People'],['legislature','Legislature'],['media','Media'],['sources','Sources']];
function dossier(){const id=state.district,e=E[id],ov=O[id];return heading(`SD ${String(id).padStart(2,'0')} · ${region(id)}`,'DISTRICT DOSSIER',`Serving member: ${esc(e.incumbent?.name||'Vacant')}. Explore the election and the district as separate, sourced records.`,`<button class="outline" data-nav="home">← Atlas</button><button class="primary" data-export-district="${id}">↓ District brief</button>`)+`<div class="workspace-body"><div class="workspace-toolbar">${selectDistrictControl()}<span class="context-chip">${esc(e.status)}</span></div><div class="dossier-full"><aside><div class="panel dossier-map-card"><div class="panel-heading"><h3>District geography</h3><span class="meta">NYS GIS</span></div>${districtMap(id)}${ov?`<div class="tab-strip"><button data-geo="neighborhoods" class="${state.geo==='neighborhoods'?'active':''}">Neighborhoods</button><button data-geo="electionDistricts" class="${state.geo==='electionDistricts'?'active':''}">Election districts</button><button data-geo="none" class="${state.geo==='none'?'active':''}">Boundary</button></div><div class="panel-foot">${esc(ov.detailedBoundaryScope)} · NYC 26c<br>${ov.neighborhoods.length} NTA intersections · ${ov.electionDistricts.length} ED polygons. Geography only; no precinct returns are inferred.</div>`:`<div class="panel-foot">Official Senate boundary. Detailed locality overlays have been collected for NYC; other county precinct outlines are not yet in this collection.</div>`}<div class="panel-body"><h3>${esc(e.leadingCandidate)}</h3><p class="muted">2026 leader · ${esc(e.leadingParty)}</p><div class="badge-row"><span class="tag">${num(e.leadVotes)}-vote lead</span><span class="tag silver">${num(e.leadPercentagePoints,2)} pt</span></div><p>${num(metric(id,'population'))} residents<br><small>ACS 2020–24 estimate</small></p></div></div></aside><section><div class="tab-strip">${dossierTabs.map(([v,l])=>`<button class="${state.tab===v?'active':''}" data-tab="${v}">${l}</button>`).join('')}</div>${dossierContent(id)}</section></div></div>`;}
function dossierContent(id){switch(state.tab){case'elections':return electionContent(id);case'money':return moneyContent(id);case'issues':return districtIssueContent(id);case'people':return peopleContent(id);case'legislature':return legislatureContent(id);case'media':return mediaContent(id);case'sources':return districtSources(id);default:return overviewContent(id);}}
function overviewContent(id){const e=E[id],m=metrics(id),p=profileFor(id),f=F[id];return `<div class="stat-row">${stat(pct(e.candidates[0]?.shareOfValidVotes),'2026 leader share','Of valid votes · unofficial')}${stat(money(metric(id,'median_household_income')),'Median household income','ACS 2020–24 · 2024 dollars')}${stat(money(f?.totalContributions,true),'Disclosed donations',`${f?.coveredCandidates||0}/${e.candidates.length} candidates · gross`) }${stat(districtEvidence(id).length,'Issue evidence records','Fresh official + dated v5 research')}</div><div class="section-heading"><h3>Who contested this seat</h3><button data-tab="elections">All results →</button></div><div class="candidate-list">${candidateCards(id,false)}</div>${e.electionDistrictsTotal===0?sourceNote('The BOE snapshot displays vote totals but a zero reporting-ED denominator for this district. Reporting completeness cannot be calculated from this field.'):''}<div class="card-grid two"><article class="research-card"><span class="eyebrow">THE SEAT</span><h3>${esc(region(id))}</h3><p>${esc(e.incumbencyNote||'')}</p><p>2024 certified winner: <b>${esc(e.history2024?.winner||'Not collected')}</b>. Current office-holder: <b>${esc(e.incumbent?.name||'Vacant')}</b>.</p><div class="source-links">${link(e.history2024?.sourceUrl,'Certified returns')} ${link(e.incumbent?.profileUrl,'Official member record')}</div></article><article class="research-card"><span class="eyebrow">DISTRICT CONTEXT</span><h3>People, work and households</h3><p>${pct(metric(id,'renter_share_pct'))} renter households · ${pct(metric(id,'foreign_born_pct'))} foreign-born residents · ${pct(metric(id,'bachelors_or_higher_pct'))} with a bachelor’s degree or above.</p><p class="muted">These are Census estimates describing residents, not estimates of political preference.</p><button class="outline small" data-tab="people">Explore 38 Census tables →</button></article></div><div class="section-heading"><h3>Policy and local reporting</h3><button data-tab="issues">Issue dossier →</button></div><div class="issue-evidence-grid">${districtEvidence(id).slice(0,4).map(evidenceCard).join('')||gap('No district-specific policy record has been collected.')}</div><div class="section-heading"><h3>Official directory profile</h3><button data-nav="candidates">Candidate desk →</button></div>${p?profileCard(p,false):gap('A current official member profile has not been collected.')}<div class="section-heading"><h3>Official district office</h3></div><article class="research-card"><p>${esc(DIR[id]?.districtOfficeAddress||'Not collected')}</p><p>District phone: ${esc(DIR[id]?.districtPhone||'Not collected')} · Albany: ${esc(DIR[id]?.albanyPhone||'Not collected')}</p><div class="source-links">${link(D.directory.meta.sourceUrl,'Official directory · 1 Sep 2026')}</div></article>`;}
function candidateTable(rows){return table(['Candidate','Ballot lines','Votes','Valid share','Result'],rows.map(c=>[esc(c.name)+(c.incumbent?' <span class="tag dark">Incumbent</span>':''),esc((c.ballotLines||[]).map(x=>`${x.party} ${num(x.votes)}`).join(' · ')),num(c.votes),pct(c.shareOfValidVotes),esc(c.resultStatus||(c.winner?'Won':'Lost'))]));}
function electionContent(id){const e=E[id];return `<div class="section-heading"><h3>2026 general election</h3><span class="tag">Unofficial · 21 Nov</span></div>${candidateTable(e.candidates)}${sourceNote(`Shares use ${num(e.validVotes)} valid votes. ${num(e.totalBallots)} total ballots; ${num(e.otherBallots?.blank)} blanks, ${num(e.otherBallots?.void)} voids and ${num(e.otherBallots?.write_in)} write-ins. ${link(e.sourceUrl,'BOE source')}. These are leading/trailing results, not certified wins/losses. Westchester emergency ballots were not fully included in the published snapshot.`)}<div class="stat-row">${stat(num(e.activeRegisteredVoters),'Active registered voters','BOE reported denominator')}${stat(num(e.totalBallots),'Ballots recorded','Unofficial general election')}${stat(e.electionDistrictsTotal?`${e.electionDistrictsReporting}/${e.electionDistrictsTotal}`:'Unavailable','Reporting election districts','As displayed by BOE')}${stat(num(e.leadVotes),'Leader’s vote margin',num(e.leadPercentagePoints,2)+' percentage points')}</div><div class="section-heading"><h3>2024 certified election</h3><span class="tag silver">Certified historical result</span></div>${e.history2024?candidateTable(e.history2024.candidates)+sourceNote(link(e.history2024.sourceUrl,'Certified 2024 returns')):gap('Historical result not collected.')}<div class="section-heading"><h3>2026 primary contests</h3></div>${(e.primaryElections||[]).map(p=>`<article class="research-card"><h3>${esc(p.party)} primary · ${esc(p.electionDate)}</h3>${candidateTable(p.candidates)}<div class="source-links">${link(p.sourceUrl,'Certified primary results')}</div></article>`).join('')||sourceNote('No contested primary result was collected for this district. This is not a claim that no candidate sought a nomination.')}<div class="section-heading"><h3>Did not reach the general ballot</h3></div>${table(['Name','Documented status','Evidence'],[...(e.primaryNonAdvancers||[]),...(e.nonContestants||[])].map(x=>[esc(x.name),esc(x.status),link(x.sourceUrl,'Source')]))}${!(e.primaryNonAdvancers?.length||e.nonContestants?.length)?sourceNote(esc(e.nonContestantsStatus)):''}<div class="section-heading"><h3>Incumbency</h3></div><article class="research-card"><h3>${esc(e.incumbent?.name||'Vacant')}</h3><p>${esc(e.incumbencyNote)}</p><div class="source-links">${link(e.incumbent?.sourceUrl||'https://www.nysenate.gov/senators-committees','Official Senate directory')}</div></article>`;}
function financeCandidate(id,name){return F[id]?.candidates.find(c=>norm(c.name)===norm(name));}
function moneyContent(id){const f=F[id];return `<div class="note-banner">Gross monetary contributions disclosed from 1 January 2025 through 22 November 2026. Public matching funds, loans, transfers and non-donation receipts are excluded. Refunds are not netted. Values describe filings, not cash on hand or influence.</div>${(f?.candidates||[]).map(c=>`<article class="research-card"><div class="profile-row">${avatar(id,c.name)}<div><span class="eyebrow">${esc(c.committeeName||c.committees?.map(x=>x.name).join(' · ')||'Committee record')}</span><h3>${esc(c.name)}</h3><div class="badge-row"><span class="tag ${c.available?'':'dark'}">${c.available?money(c.totalContributions)+' collected':'Collection gap'}</span><span class="tag silver">${c.available?num(c.transactionCount)+' transactions':'Transaction count not collected'}</span></div></div></div>${c.available?`<div class="donor-list">${(c.donors||[]).slice(0,10).map((r,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span><strong>${esc(r.name)}</strong><small>${esc(r.type||'Disclosed contributor')} · ${num(r.transactions)} transaction${r.transactions===1?'':'s'}</small></span><em>${money(r.amount)}</em></div>`).join('')}</div>`:gap(c.note||c.status||'No verified committee donation total is available for this candidate.')}<p class="meta-line">${esc(c.committeeMappingStatus||'')} · Last transaction ${esc(c.lastTransactionDate||'not available')}</p><div class="source-links">${link(c.sourceUrl||c.publicSearchUrl,'Official transaction query')}${(c.committees||[]).slice(0,2).map(x=>link(x.sourceUrl||c.committeeMappingSource,'Committee '+x.filerId)).join('')}</div></article>`).join('')}${sourceNote('Rankings show the ten largest normalized contributor-name groups per candidate. Name groups can contain homonyms; spelling variants may remain separate. Residential addresses and private contact details are omitted.')}`;}
function moneyWorkspace(){return heading('Campaign finance','MONEY & NETWORKS','Follow disclosed contributions from committees to candidates. Inspect coverage and donor groups before drawing comparisons.',`<button class="outline" data-nav="sources">Methodology & sources</button>`)+`<div class="workspace-body"><div class="workspace-toolbar">${selectDistrictControl()}<div class="tab-strip"><button data-finance-view="donors" class="${state.financeView==='donors'?'active':''}">Candidate donors</button><button data-finance-view="network" class="${state.financeView==='network'?'active':''}">Shared contributor names</button></div></div><div class="stat-row">${stat('103 / 112','Candidates with data','Coverage varies by district')}${stat('63','Districts represented','At least one covered candidate each')}${stat('2025–26','Collection period','1 Jan 2025 – 22 Nov 2026')}${stat('9','Candidate collection gaps','Missing is not zero')}</div>${state.financeView==='network'?donorNetwork(state.district):moneyContent(state.district)}</div>`;}
function donorNetwork(id){const own=(F[id]?.candidates||[]).filter(c=>c.available);let left=[];for(const c of own)for(const donor of c.donors||[])left.push({candidate:c.name,donor:donor.name,amount:donor.amount,key:norm(donor.name),type:donor.type});left=left.sort((a,b)=>b.amount-a.amount).slice(0,8);const hits=[];for(const f of Object.values(F))if(f.district!==id)for(const c of f.candidates||[])for(const d of c.donors||[])if(left.some(x=>x.key===norm(d.name)))hits.push({district:f.district,candidate:c.name,donor:d.name,amount:d.amount,key:norm(d.name)});const right=hits.sort((a,b)=>b.amount-a.amount).slice(0,10),donors=[...new Map(left.reduce((acc,x)=>{const old=acc.find(y=>y[0]===x.key);if(old)old[1].amount+=x.amount;else acc.push([x.key,{...x}]);return acc;},[])).values()].slice(0,7);return `<div class="note-banner">Connections mean the same normalized contributor name appears in two candidates’ collected top-ten lists. This is a research lead, not a confirmed shared identity or evidence of coordination. The collection excludes donations outside those rankings.</div><article class="research-card"><h3>SD ${id} · disclosed contributor-name connections</h3><div class="network-wrap"><svg viewBox="0 0 1000 430" role="img" aria-label="Shared contributor-name network">${donors.map((d,i)=>{const y=55+i*49;return `<path class="network-edge" d="M170 215 C340 215 310 ${y} 460 ${y}" stroke="#ac9869" stroke-width="1.4"/>${right.map((r,j)=>r.key===d.key?`<path class="network-edge" d="M570 ${y} C670 ${y} 680 ${30+j*38} 800 ${30+j*38}" stroke="#968661" stroke-width="1"/>`:'').join('')}<g class="network-node"><circle cx="470" cy="${y}" r="4" fill="#d8bd78"/><text x="483" y="${y-5}" fill="#e7d6aa" font-size="11">${esc(short(d.donor,27))}</text><text x="483" y="${y+10}" fill="#939c98" font-size="9">${money(d.amount)} → selected district</text></g>`;}).join('')}<circle cx="150" cy="215" r="52" fill="#171c1a" stroke="#d4ba77" stroke-width="2"/><text x="150" y="212" text-anchor="middle" fill="#e9d3a2" font-size="25">SD ${id}</text><text x="150" y="234" text-anchor="middle" fill="#adb6af" font-size="10">${own.length} CANDIDATES</text>${right.map((r,j)=>`<g class="network-node" data-open-district="${r.district}" role="button" tabindex="0"><circle cx="805" cy="${30+j*38}" r="3" fill="#c3ba9e"/><text x="820" y="${30+j*38+4}" fill="#d8ddd5" font-size="11">SD ${r.district} · ${esc(short(r.candidate,20))}</text></g>`).join('')}</svg></div>${right.length?'':sourceNote('No exact shared name appears in the other collected top-ten rankings for these selected contributors.')}<div class="network-caption">Contributor names grouped by normalized text · click a connected district to inspect its actual filings.</div></article>${table(['Contributor name','Other candidate','District','Disclosed amount'],right.map(r=>[esc(r.donor),esc(r.candidate),`<button data-open-district="${r.district}">SD ${r.district} →</button>`,money(r.amount)]))}`;}
function evidenceCard(r){let date=r.publishedAt||r.sourceDates?.map(x=>x.publishedAt).filter(Boolean).join(' · ')||'Source date in record';return `<article class="research-card"><div class="badge-row"><span class="tag ${r.freshlyVerified?'silver':'dark'}">${esc(r.evidenceType||'Research record')}</span>${r.district?`<button class="tag" data-open-district="${r.district}">SD ${r.district}</button>`:''}</div><h3>${esc(r.candidate||r.candidates?.join(' / ')||short(r.title||'District context',100))}</h3><p>${esc(r.summary||r.text||'')}</p><p class="meta-line">${esc(date)} · ${r.freshlyVerified?'Source freshly retrieved':'Imported v5 research · 20 Nov snapshot'}</p>${r.limitations?.length?`<p class="muted">${esc(r.limitations.join(' '))}</p>`:''}<div class="source-links">${(r.sourceUrls?.length?r.sourceUrls:[r.sourceUrl]).filter(Boolean).slice(0,4).map((u,i)=>link(u,r.sourceIds?.[i]||'Source')).join('')}</div></article>`;}
function districtIssueContent(id){const rows=districtEvidence(id);return `<div class="section-heading"><h3>District policy evidence</h3><span class="tag">${rows.length} records</span></div><div class="issue-chips">${districtIssues(id).map(x=>`<button class="issue-chip" data-issue="${x.id}" data-issue-district="${id}">${esc(x.title)}</button>`).join('')}</div>${sourceNote('Evidence cards preserve named candidate statements, local reporting and original dates. A district’s demographic composition is never treated as its policy preference. Imported handoff records remain marked until their source is freshly rechecked.')}<div class="issue-evidence-grid">${rows.map(evidenceCard).join('')||gap('No explicit district issue evidence has been collected.')}</div>${evidence.filter(x=>x.district===id&&x.isGap).length?`<details class="research-card"><summary>Open research gaps (${evidence.filter(x=>x.district===id&&x.isGap).length})</summary>${evidence.filter(x=>x.district===id&&x.isGap).map(x=>`<p>${esc(x.summary)}</p>`).join('')}</details>`:''}`;}
function groupChart(group){if(!group)return gap('This table was not collected.');let items=group.items.filter(x=>x.share!=null).sort((a,b)=>b.share-a.share);return `<article class="research-card"><h3>${esc(group.title)}</h3><p class="meta-line">${esc(group.universe)} · ${esc(group.period)} · ${esc(group.table)}</p><div class="metric-bars">${items.map(x=>`<div class="metric-bar"><div class="label"><span>${esc(x.label)}</span><b>${pct(x.share)} <small class="muted">±${num(x.shareMoe90,2)} pp</small></b></div><div class="track"><i style="width:${Math.min(100,Math.max(0,x.share))}%"></i></div><small>${num(x.count)} ±${num(x.countMoe90)} ${x.quality==='high_sampling_uncertainty'?'· high sampling uncertainty':''}</small></div>`).join('')}</div><div class="source-links">${link(group.officialSourceUrl||group.sourceUrl,'Census table '+group.table)}${link(group.sourceUrl,'Retrieved source data')}</div>${sourceNote(`90% margins of error shown. ${group.partition?'Categories partition the stated universe.':'Categories may overlap; do not add shares without consulting the table definition.'}`)}</article>`;}
function peopleContent(id){const m=metrics(id),groups=C[id]?.groups||{};return `<div class="note-banner">Freshly collected from Census-origin ACS 2024 five-year tables on 23 November 2026. Survey period: 2020–2024. Estimates and 90% margins of error describe residents and households; they do not measure vote choice.</div><div class="stat-row">${stat(num(metric(id,'population')),'Population','±'+num(m.population?.moe)+' · 90% MOE')}${stat(money(metric(id,'median_household_income')),'Median household income','±'+money(m.median_household_income?.moe))}${stat(pct(metric(id,'renter_share_pct')),'Renter households','±'+num(m.renter_share_pct?.moe,2)+' pp')}${stat(pct(metric(id,'poverty_rate_pct')),'Below poverty level','±'+num(m.poverty_rate_pct?.moe,2)+' pp')}</div><div class="workspace-toolbar"><label>Explore a population table <select id="peopleGroup">${Object.entries(groups).map(([k,g])=>`<option value="${k}" ${state.peopleGroup===k?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label></div>${groupChart(groups[state.peopleGroup])}<details class="research-card"><summary>All ${C[id]?.metrics.length||0} district indicators with margins of error</summary>${table(['Indicator','Estimate','90% MOE','Universe','Source'],(C[id]?.metrics||[]).map(x=>[esc(x.label),x.unit==='USD'?money(x.value):num(x.value,x.unit==='percent'||x.unit==='years'?2:0)+(x.unit==='percent'?'%':''),num(x.moe,2),esc(x.universe),link(x.officialSourceUrl||x.sourceUrl,x.table)]))}</details>`;}
function peopleWorkspace(){return heading('People & communities','THE DISTRICT BENEATH THE VOTE','Explore people, work, housing, families and the public institutions recorded in v5. Keep measured estimates separate from research hypotheses.')+`<div class="workspace-body"><div class="workspace-toolbar">${selectDistrictControl()}<div class="tab-strip"><button data-people-tab="census" class="${state.peopleTab==='census'?'active':''}">Census tables</button><button data-people-tab="institutions" class="${state.peopleTab==='institutions'?'active':''}">Institutions & context</button></div></div>${state.peopleTab==='census'?peopleContent(state.district):researchCatalog()}</div>`;}
function researchCatalog(){return `<div class="note-banner">These research catalogs come from the supplied 20 November v5 plan. Associations are descriptive context and source leads. They do not establish a community’s political preference or an individual’s identity.</div>${Object.entries(D.handoff.researchGroups).map(([name,groups])=>`<details class="research-card"><summary>${esc(name.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase()))} · ${groups.length} table${groups.length===1?'':'s'}</summary>${groups.map(t=>`<h3>${esc(t.title)}</h3>${structuredTable(t)}`).join('')}</details>`).join('')}`;}
function structuredTable(t){return table((t.headers||[]).map(esc),(t.rows||[]).map(row=>row.map(x=>esc(typeof x==='object'?JSON.stringify(x):x))))+(t.links?.length?`<div class="source-links">${t.links.map(x=>typeof x==='string'?link(x,'Source'):link(x.href||x.url,x.text||x.label||'Source')).join('')}</div>`:'');}
function issueWorkspace(){const issue=issues.find(x=>+x.id===state.issue)||issues[0],records=issueEvidence(issue.id).filter(r=>(!state.filterDistrict||r.district===state.filterDistrict)&&(state.filterEvidence==='all'||(state.filterEvidence==='fresh'?r.freshlyVerified:state.filterEvidence==='candidate'?r.evidenceType==='Candidate position':!r.freshlyVerified))&&(state.filterCandidate==='all'||r.candidate===state.filterCandidate||(r.candidates||[]).includes(state.filterCandidate)));const districtCount=new Set(issueEvidence(issue.id).map(x=>x.district).filter(Boolean)).size;return heading('Issue intelligence','20 CONNECTED POLICY TRACKS','Move from the statewide issue to the bill, a named candidate’s statement and the district’s documented context.')+`<div class="workspace-body issue-layout"><aside class="panel issue-list">${issues.map(x=>`<button class="${x.id===issue.id?'active':''}" data-select-issue="${x.id}"><b>${String(x.id).padStart(2,'0')}</b><span>${esc(x.title)}<small>${issueEvidence(x.id).length} evidence records</small></span></button>`).join('')}</aside><section><div class="issue-view-head"><span class="eyebrow">ISSUE ${String(issue.id).padStart(2,'0')}</span><h2>${esc(issue.title)}</h2><p>${esc(issue.definition||issue.description)}</p><p class="meta-line">Issue scope from the v5 brief · 20 Nov 2026. Current legislative definitions and status appear in the official records below.</p><div class="badge-row"><span class="tag">${districtCount} districts with records</span><span class="tag silver">${(issue.officialSources||[]).length} freshly checked official sources</span></div></div><div class="workspace-split"><article class="research-card"><h3>Evidence geography</h3><div class="issue-map-small">${issueMap(issue.id)}</div><p class="meta-line">Gold intensity counts collected evidence. An uncolored seat means no linked record in this collection, not opposition or indifference.</p></article><article class="research-card"><h3>Fresh official record</h3>${(issue.officialSources||[]).map(s=>`<p>${link(s.sourceUrl,s.title)}</p><small class="fresh-data">Retrieved ${esc(s.retrievedAt)}</small>`).join('')||gap('Official issue source is being collected.')}<details><summary>v5 issue brief · 20 Nov snapshot</summary><p>${esc(issue.whyItMattered||'')}</p><p>${esc(issue.regionsAndDistricts||'')}</p><p><b>Collection gaps:</b> ${esc(issue.knownGaps||'See evidence records.')}</p></details></article></div><div class="workspace-toolbar"><label>Evidence location <select id="issueDistrict">${districtOptions(state.filterDistrict,true)}</select></label><label>Named person <select id="issueCandidate"><option value="all">All named people</option>${[...new Set(issueEvidence(issue.id).filter(r=>!state.filterDistrict||r.district===state.filterDistrict).flatMap(r=>[r.candidate,...(r.candidates||[])]).filter(Boolean))].sort().map(n=>`<option value="${esc(n)}" ${state.filterCandidate===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Evidence type <select id="evidenceFilter"><option value="all">All evidence</option><option value="fresh" ${state.filterEvidence==='fresh'?'selected':''}>Fresh official records</option><option value="candidate" ${state.filterEvidence==='candidate'?'selected':''}>Candidate statements</option><option value="imported" ${state.filterEvidence==='imported'?'selected':''}>Imported v5 research</option></select></label><span class="context-chip">${records.length} records</span></div><div class="issue-evidence-grid">${records.slice(0,100).map(evidenceCard).join('')||gap('No collected evidence matches these filters. Select all districts or another evidence type.')}</div>${records.length>100?sourceNote(`Showing the first 100 of ${records.length} records. Select a district to inspect its full evidence.`):''}<div class="section-heading"><h3>Related legislation</h3></div>${(D.issueEvidence.legislation||[]).filter(b=>(b.issueIds||[]).includes(issue.id)).map(b=>billCard(b,state.filterDistrict||null)).join('')||sourceNote('No bill has yet been matched to this issue.')}</section></div>`;}
function issueMap(id){let old=state.heat,issue=state.issue;state.heat='issues';state.issue=id;let html=svgMap({id:'issueMap',classes:'issue-map-svg'});state.heat=old;state.issue=issue;return html;}
function profileCard(p,full=true){return `<article class="research-card"><div class="profile-row">${avatar(p.district,p.name)}<div><span class="eyebrow">SD ${p.district} · OFFICIAL SENATE PROFILE</span><h3>${esc(p.name)}</h3><p class="meta-line">${esc(p.profileStatus)}</p><p>${esc(p.biographyExcerpt||short(p.biography,550)||'No biography collected.')}</p><div class="source-links">${link(p.aboutUrl||p.profileUrl,'Full official biography')}</div></div></div>${full?`<div class="section-heading"><h3>Committee assignments</h3></div>${(p.committees||[]).length?table(['Committee','Role'],p.committees.map(c=>[link(c.sourceUrl,c.name),esc(c.role)])):sourceNote('No committee assignments were parsed from the official profile.')}<p class="meta-line">Biography is office-authored; it is not an independent assessment. Retrieved ${esc(p.retrievedAt)}.</p>`:''}<p class="meta-line">${esc(p.headshotAttribution||'Photo: New York State Senate.')} ${link(p.imagePolicyUrl||'https://www.nysenate.gov/policies-and-waivers',p.imageLicense||'Image permissions')}</p></article>`;}
function candidateWorkspace(){const id=state.district,e=E[id],p=profileFor(id);return heading('Candidate & member profiles','THE PEOPLE BEHIND THE SEATS','Distinguish the candidates on the ballot, the serving member and the certified historical record.')+`<div class="workspace-body"><div class="workspace-toolbar">${selectDistrictControl()}<button class="outline" data-open-dossier="1">Full district dossier →</button></div><div class="card-grid two">${e.candidates.map(c=>{let pr=profileFor(id,c.name),fi=financeCandidate(id,c.name),records=districtEvidence(id).filter(r=>r.candidate===c.name||(r.candidates||[]).includes(c.name));return `<article class="research-card"><div class="profile-row">${avatar(id,c.name)}<div><span class="eyebrow">${esc(c.party)} · ${c.incumbent?'INCUMBENT ON BALLOT':'GENERAL-ELECTION CANDIDATE'}</span><h3>${esc(c.name)}</h3><p>${esc(c.resultStatus)} · ${pct(c.shareOfValidVotes)} valid votes</p><p>${num(c.votes)} votes · ${esc(c.ballotLines.map(x=>x.party).join(' / '))}</p></div></div><div class="badge-row"><span class="tag">${fi?.available?money(fi.totalContributions)+' donations':'Finance collection gap'}</span><span class="tag silver">${records.length} linked records</span></div>${pr?`<p>${esc(pr.biographyExcerpt||short(pr.biography,450))}</p>${link(pr.profileUrl,'Official profile')}`:sourceNote('An independently verified biography and portrait have not been collected for this candidate.')}<div class="source-links">${link(e.sourceUrl,'Election returns')}${fi?.sourceUrl?link(fi.sourceUrl,'Disclosed donations'):''}</div>${records.slice(0,2).map(r=>`<details><summary>${esc(short(r.title,95))}</summary><p>${esc(r.summary)}</p>${link(r.sourceUrl,'Source')}</details>`).join('')}</article>`;}).join('')}</div><div class="section-heading"><h3>Official member directory record</h3></div>${p?profileCard(p,true):gap('No official member profile collected.')}<div class="section-heading"><h3>Earlier field and primary candidates</h3></div>${table(['Name','Recorded status','Source'],[...(e.primaryNonAdvancers||[]),...(e.nonContestants||[])].map(x=>[esc(x.name),esc(x.status),link(x.sourceUrl,'Record')]))}</div>`;}
function billCard(b,id=null){const votes=(b.rollCalls||[]).flatMap(v=>(v.members||[]).filter(x=>!id||x.district===id).map(x=>({...x,date:v.date,voteType:v.type,sourceUrl:v.sourceUrl,billVersion:v.billIdAsDisplayed||v.votedBillId||v.billId||b.billId})));return `<article class="research-card"><div class="badge-row"><span class="tag">${esc(b.billId)} · ${esc(b.session)}</span><span class="tag silver">${esc(b.currentStatus)}</span></div><h3>${esc(b.title)}</h3><p>${esc(b.summary)}</p><p class="meta-line">Sponsor: ${esc(b.sponsor?.name||'Not collected')} · Last action ${esc(b.latestAction?.date||'')}: ${esc(b.latestAction?.action||'')}</p>${(b.rollCalls||[]).map(v=>`<div class="badge-row"><span class="tag dark">${esc(v.date)} · ${esc(v.type)} · ${esc(v.billIdAsDisplayed||v.votedBillId||v.billId||b.billId)}</span>${Object.entries(v.totals||{}).map(([k,n])=>`<span class="tag ${k==='aye'?'':'silver'}">${esc(k)} ${n}</span>`).join('')}</div>`).join('')}${id?`<div class="inline-detail"><b>SD ${id} · recorded legislative activity</b>${votes.length?`<p>${votes.map(x=>`${esc(x.name)}: <strong>${esc(x.vote.toUpperCase())}</strong> · ${esc(x.date)} (${esc(x.voteType)})`).join('<br>')}</p>`:'<p>No named vote for this district was collected on this bill.</p>'}${b.sponsor?.district===id?'<p>Primary sponsor</p>':''}${b.cosponsors?.some(x=>x.district===id)?'<p>Named co-sponsor in the official record</p>':''}</div>`:`<details><summary>Named votes (${votes.length}) and bill actions</summary>${table(['Member','District','Vote','Date'],votes.map(x=>[esc(x.name),`<button data-open-district="${x.district}">SD ${x.district}</button>`,esc(x.vote),esc(x.date)]))}<div class="record-timeline">${(b.actions||[]).map(a=>`<div><time>${esc(a.date)}</time><p>${esc(a.action)}</p></div>`).join('')}</div></details>`}<div class="source-links">${link(b.sourceUrl,'Official bill and roll call')}</div><p class="meta-line">Retrieved ${esc(b.retrievedAt)}. ${esc(b.statusNote||'Chamber passage is distinct from enactment.')}</p>${b.limitations?.length?sourceNote(esc(b.limitations.join(' '))):''}</article>`;}
function legislatureContent(id=null){const bills=(D.issueEvidence.legislation||[]).filter(b=>!id||b.sponsor?.district===id||(b.cosponsors||[]).some(x=>x.district===id)||(b.rollCalls||[]).some(v=>(v.members||[]).some(x=>x.district===id)));return `${sourceNote('Votes, sponsors, committee actions and campaign statements are different evidence types. The record retains the actual member serving on each vote date; it is not attributed to a later winner or incoming member.')}<div class="section-heading"><h3>${id?'SD '+id+' · ':''}Collected bills</h3><span class="tag silver">${bills.length} official records</span></div>${bills.map(b=>billCard(b,id)).join('')||gap('No bill or named roll call has been matched to this district in this collection.')}`;}
function legislatureWorkspace(){return heading('Legislative intelligence','BILLS · SPONSORS · ROLL CALLS','Read actual legislative activity and its procedural status. Open the primary source for full bill text and amendments.')+`<div class="workspace-body"><div class="workspace-toolbar"><label>Record scope <select id="legislatureDistrict">${districtOptions(state.filterDistrict,true)}</select></label><span class="fresh-data">Official sources retrieved 23 Nov 2026</span></div>${legislatureContent(state.filterDistrict||null)}</div>`;}
function mediaRecords(id){const official=profiles.filter(p=>!id||p.district===id).flatMap(p=>(p.newsroomItems||[]).map((r,i)=>({id:'news-'+p.district+'-'+i,district:p.district,publisher:p.name+' · Senate office',platform:'Senate newsroom',publishedAtLabel:'Discovered '+r.discoveredAt,summary:r.title,sourceUrl:r.url,evidenceType:'Official newsroom link',freshlyVerified:true,note:r.titleMethod})));const imported=(D.handoff.media||[]).filter(r=>!id||(r.districts||[]).includes(id)),old=id?(R[id]?.media_records||[]):[];return [...official,...imported,...old].filter((r,i,a)=>a.findIndex(x=>(x.sourceUrl||x.source_url||x.url)===(r.sourceUrl||r.source_url||r.url))===i);}
function mediaContent(id=null){let rows=mediaRecords(id).filter(r=>state.mediaPlatform==='all'||(r.platform||'').toLowerCase().includes(state.mediaPlatform.toLowerCase()));return `<div class="note-banner">Official newsroom statements are office-authored. Social and media records imported from v5 retain their historical snapshot. Discovery dates are not publication dates. External sources open in the same tab.</div><div class="workspace-toolbar"><label>Channel <select id="mediaPlatform">${['all','Senate','X','YouTube','Reddit'].map(p=>`<option value="${p}" ${state.mediaPlatform===p?'selected':''}>${p==='all'?'All channels':p}</option>`).join('')}</select></label><span class="context-chip">${rows.length} records</span></div><div class="card-grid two">${rows.slice(0,100).map(r=>`<article class="research-card"><div class="badge-row"><span class="tag ${r.freshlyVerified?'silver':'dark'}">${esc(r.platform||r.type||'Source record')}</span>${r.district?`<button class="tag" data-open-district="${r.district}">SD ${r.district}</button>`:''}</div><h3>${esc(r.publisher||r.author||r.title||'Source record')}</h3><p>${esc(r.summary||r.headline||r.description||r.note||'Open the original source.')}</p><p class="meta-line">${esc(r.publishedAtLabel||r.published_at||r.publishedAt||'Publication date not recorded')} · ${esc(r.evidenceType||r.evidence_type||'Historical research')}</p>${r.note?`<small class="muted">${esc(r.note)}</small>`:''}<div class="source-links">${link(r.sourceUrl||r.source_url||r.url,'Read original source')}</div></article>`).join('')||gap('No record matches this channel and district.')}</div>${rows.length>100?sourceNote('Showing 100 records. Select a district to inspect its complete set.'):''}`;}
function mediaWorkspace(){return heading('Media desk','NEWSROOMS · REPORTING · PUBLIC PLATFORMS','A dated source desk connecting district reporting, public statements and the media catalogs in v5.')+`<div class="workspace-body"><div class="workspace-toolbar"><label>District <select id="mediaDistrict">${districtOptions(state.filterDistrict,true)}</select></label></div>${mediaContent(state.filterDistrict||null)}<details class="research-card"><summary>Community media and platform research catalogs</summary>${['ethnicMedia','platforms','reddit'].map(k=>(D.handoff.researchGroups[k]||[]).map(t=>`<h3>${esc(t.title)}</h3>${structuredTable(t)}`).join('')).join('')}</details></div>`;}
function compareWorkspace(){const a=state.compareA,b=state.compareB;const keys=['population','median_age','median_household_income','bachelors_or_higher_pct','foreign_born_pct','renter_share_pct','rent_burden_30_plus_pct','poverty_rate_pct','age_18_34_pct','age_65_plus_pct','household_living_alone_pct','households_no_workers_pct','households_two_workers_pct','work_from_home_pct'];return heading('Compare districts','COMMON DEFINITIONS · DIFFERENT PLACES','Compare the same election and Census measures. Missing finance coverage remains visible beside the totals.',`<button class="outline" data-export-comparison="1">↓ Comparison CSV</button>`)+`<div class="workspace-body"><div class="compare-selects"><label>District A <select id="compareA">${districtOptions(a)}</select></label><span>VS</span><label>District B <select id="compareB">${districtOptions(b)}</select></label></div><div class="card-grid two">${[a,b].map(id=>`<article class="research-card"><span class="eyebrow">SD ${id}</span><h3>${esc(region(id))}</h3>${districtMap(id,false)}<h3>${esc(E[id].leadingCandidate)}</h3><p>${esc(E[id].leadingParty)} · ${num(E[id].leadPercentagePoints,2)} pt lead · unofficial</p><button class="outline" data-open-district="${id}">Open full dossier →</button></article>`).join('')}</div>${table(['Measure',`SD ${a}`,`SD ${b}`,'Period / definition'],[['2026 leading candidate',esc(E[a].leadingCandidate),esc(E[b].leadingCandidate),'BOE 21 Nov · unofficial'],['2026 leader margin',num(E[a].leadPercentagePoints,2)+' pt',num(E[b].leadPercentagePoints,2)+' pt','Percentage points of valid votes'],['2024 certified winner',esc(E[a].history2024?.winner),esc(E[b].history2024?.winner),'Certified 2024 result'],['Gross disclosed contributions',money(F[a]?.totalContributions),money(F[b]?.totalContributions),'1 Jan 2025–22 Nov 2026; coverage differs'],['Finance candidate coverage',`${F[a]?.coveredCandidates}/${E[a].candidates.length}`,`${F[b]?.coveredCandidates}/${E[b].candidates.length}`,'Missing totals are not zero'],...keys.map(k=>{const x=metrics(a)[k],y=metrics(b)[k];return [esc(x?.label||k),formatMetric(x)+' <small>±'+num(x?.moe,2)+'</small>',formatMetric(y)+' <small>±'+num(y?.moe,2)+'</small>','ACS 2020–24; 90% margin of error'];})])}<div class="section-heading"><h3>Issue evidence side by side</h3></div><div class="card-grid two">${[a,b].map(id=>`<section><h3>SD ${id}</h3>${districtEvidence(id).slice(0,6).map(evidenceCard).join('')}</section>`).join('')}</div></div>`;}
function formatMetric(m){return !m?'—':m.unit==='USD'?money(m.value):num(m.value,m.unit==='percent'||m.unit==='years'?1:0)+(m.unit==='percent'?'%':'');}
const layerRoutes={1:'districts',2:'districts',3:'people',4:'issues',5:'people',6:'people',7:'money',8:'legislature',9:'issues',10:'districts',11:'media',12:'layers',13:'candidates',14:'issues',15:'sources',16:'people',17:'media',18:'media',19:'people',20:'people',21:'people',22:'atlas',23:'media',24:'migration'};
const layerStatus={1:'2024 certified + 2026 unofficial returns; 2022 not yet joined',2:'4,214 NYC EDs and 262 NTAs; remaining counties pending',3:'38 ACS tables across all 63 Senate districts',4:'20 issues; named statements and official evidence',5:'ACS occupation/industry plus imported profession catalog',6:'Imported ten-segment student research catalog',7:'103 candidate donation records; issue-linked lobbying sources',8:'16 official bills; collected named roll calls',9:'Evidence records; comprehensive endorsement graph pending',10:'BOE ballots and registration; causal mobilization estimates absent',11:'Official newsrooms and dated v5 media logs',12:'Model specification only; no validated forecast produced',13:'112 general-election candidates; 63 official member profiles',14:'Dated source and bill event history',15:'v5 research framework; no campaign recommendation generated',16:'Fresh household, worker, income and life-stage tables',17:'Imported public-source catalog; not representative polling',18:'Imported platform catalog with source links',19:'ACS race, ancestry, origin, language and birthplace tables',20:'Imported institutional catalog; no alumni voting inference',21:'Fresh employment tables and expanded research catalog',22:'All 63 official Senate shapes; 28 NYC district detail views',23:'Official newsroom records and imported candidate media',24:'Six IRS migration vintages, PEP2025 and 17 v5 figures'};
function layersWorkspace(){return heading('The intelligence architecture','24 LAYERS · ONE CONNECTED WORKSPACE','Each layer opens its working view and states exactly what has been collected. Research specifications remain visible where evidence is still incomplete.')+`<div class="workspace-body"><div class="card-grid">${D.handoff.layers.map(l=>`<article class="research-card layer-card"><span class="layer-number">${String(l.id).padStart(2,'0')}</span><span class="eyebrow">${esc(l.phase||'RESEARCH')} · ${esc(l.evidenceType)}</span><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p><div class="inline-detail">${esc(layerStatus[l.id]||'See source record.')}</div><p class="meta-line">${esc(l.sources)}</p><button class="outline small" data-layer="${l.id}">${l.id===12?'Read model specification':'Open working layer'} →</button>${state.layer===l.id&&l.id===12?`<div class="inline-detail"><h3>Forecasting & backtest</h3><p>No probability or prediction is published in this build. A validated model requires historical district boundaries, results, a declared training window and an out-of-sample backtest. The terminal currently provides observed returns, source-based comparisons and the v5 specification.</p><button data-nav="sources" class="outline small">Read the research plan</button></div>`:''}</article>`).join('')}</div></div>`;}
function freshMigrationChart(rows,key='returns'){const vals=rows.map(x=>x.net[key]),max=Math.max(...vals.map(Math.abs),1);return `<svg class="migration-chart" viewBox="0 0 760 280" role="img" aria-label="Net domestic tax-return migration by IRS vintage"><path d="M40 235H730" stroke="#616862"/>${rows.map((r,i)=>{let h=Math.abs(r.net[key])/max*172,x=64+i*112;return `<rect x="${x}" y="${235-h}" width="65" height="${h}" rx="2" fill="${r.methodBreak?'#9a8c66':'#c4ad72'}" opacity=".85"><title>${esc(r.period)}: ${num(r.net[key])} net ${esc(key)}</title></rect><text x="${x+32}" y="${225-h}" text-anchor="middle" fill="#e1d5b5" font-size="13">${key==='agiUsd'?'$'+num(r.net[key]/1e9,2)+'B':num(r.net[key])}</text><text x="${x+32}" y="256" text-anchor="middle" fill="#bbc0b9" font-size="11">${esc(r.period)}</text>${r.methodBreak?`<text x="${x+32}" y="271" text-anchor="middle" fill="#9ca398" font-size="8">METHOD CHANGE</text>`:''}`;}).join('')}</svg>`;}
function migrationWorkspace(){const m=D.migrationFresh||{},last=m.nyc?.at(-1),ny=m.newYorkState?.at(-1);return heading('Migration & real estate','WHERE PEOPLE AND INCOME MOVE','Compare source-native migration flows, population change and the property series in the master plan.')+`<div class="workspace-body"><div class="tab-strip"><button data-migration-tab="fresh" class="${state.migrationTab==='fresh'?'active':''}">Fresh IRS & Census data</button><button data-migration-tab="figures" class="${state.migrationTab==='figures'?'active':''}">17 research figures</button><button data-migration-tab="county" class="${state.migrationTab==='county'?'active':''}">District’s county context</button></div>${state.migrationTab==='figures'?migrationFigures():state.migrationTab==='county'?countyMigrationView():`<div class="note-banner">IRS tax returns approximate households; exemptions approximate people represented by returns. Mover AGI is income, not tax revenue. The IRS matching method changes in 2022–2023. County and state figures are not allocated to Senate districts.</div><div class="stat-row">${stat(num(last?.net.returns),'NYC net tax-return movers',last?.period||'')}${stat('$'+num((last?.net.agiUsd||0)/1e9,2)+'B','NYC net mover AGI','Domestic flows · year 2 AGI')}${stat(num(ny?.net.returns),'NYS net tax-return movers',ny?.period||'')}${stat('6','IRS migration vintages','2018–19 through 2023–24')}</div><div class="card-grid two"><article class="research-card"><h3>New York City · net domestic tax-return movers</h3><p class="meta-line">Five counties combined; inter-borough flows removed</p>${freshMigrationChart(m.nyc||[])}${link(m.sources?.find(s=>s.id==='IRS_2324')?.url||'https://www.irs.gov/statistics/soi-tax-stats-migration-data-2023-2024','IRS official release')}</article><article class="research-card"><h3>New York State · net interstate mover AGI</h3><p class="meta-line">Inflow minus outflow · dollars in year 2 of each vintage</p>${freshMigrationChart(m.newYorkState||[],'agiUsd')}${link('https://www.irs.gov/statistics/soi-tax-stats-migration-data-2023-2024','IRS official release')}</article></div><div class="section-heading"><h3>Full observed migration series</h3></div>${table(['Geography','Period','Inflow returns','Outflow returns','Net returns','Net AGI'],[...(m.nyc||[]),...(m.newYorkState||[])].map(r=>[esc(r.geography),esc(r.period),num(r.inflow.returns),num(r.outflow.returns),num(r.net.returns),money(r.net.agiUsd)]))}<div class="section-heading"><h3>Where New York connects · 2023–2024</h3></div>${table(['Partner state','Inflow returns','Outflow returns','Net returns','Net AGI'],(m.statePartners||[]).filter(x=>x.vintage==='2324').sort((a,b)=>a.net.returns-b.net.returns).map(r=>[esc(r.stateName),num(r.inflow.returns),num(r.outflow.returns),num(r.net.returns),money(r.net.agiUsd)]))}<details class="research-card"><summary>NYC population change components · Census PEP</summary>${table(['Year','Domestic migration','International migration','Natural change','Estimate vintage'],(m.nycPopulationComponents||[]).map(r=>[r.year,num(r.domesticMigration),num(r.internationalMigration),num(r.naturalChange),r.estimateVintage]))}<p class="meta-line">Persons, not tax returns. Estimate vintages use different Census bases; the 2020 partial period is omitted.</p></details>`}</div>`;}
function migrationFigures(){return `<div class="note-banner">Original figures from the supplied v5 research. Each retains its source period and geographic unit. Newly collected numeric series are available in the IRS & Census tab. A plotted geographic correlation is not an individual voting effect.</div><div class="migration-grid">${(D.handoff.migration.charts||[]).map(c=>`<article class="research-card chart-card"><span class="eyebrow">${esc(c.sectionTitle||c.section||'V5 RESEARCH FIGURE')}</span><h3>${esc(c.title)}</h3><img src="assets/${esc(c.file.replace(/\.png$/,'.svg'))}" alt="${esc(c.title)}" loading="lazy"><p class="chart-caption">${esc(c.subtitle||c.caption||'')}</p><p class="meta-line">${esc(c.sourceText||c.sourceState||'Imported 20 Nov 2026 research')}</p><details><summary>Underlying record and source notes</summary><pre class="chart-data">${esc(JSON.stringify(c.freshData||c.data||{note:'Numeric table not reproduced in this figure record.'},null,2))}</pre></details></article>`).join('')}</div><details class="research-card"><summary>All migration and property research tables</summary>${(D.handoff.migration.tables||[]).map(t=>`<h3>${esc(t.title)}</h3>${structuredTable(t)}`).join('')}</details>`;}
function countyMigrationView(){const m=D.migrationFresh,context=m.districtCountyContext?.find(x=>x.district===state.district),fips=context?.countyContext.map(c=>c.countyFips)||[],rows=m.countyMigration?.filter(x=>fips.includes(x.countyFips))||[];return `<div class="workspace-toolbar">${selectDistrictControl()}</div><div class="note-banner">${esc(context?.geographicCaution||'County statistics cover whole counties, including places outside this district. No district estimate is inferred.')}</div><h3>SD ${state.district} · ${esc(context?.sourceDescription||region(state.district))}</h3>${table(['Whole-county context','Period','Inflow returns','Outflow returns','Net returns','Net AGI'],rows.map(r=>[esc(r.countyName),esc(r.period),num(r.inflow.returns),num(r.outflow.returns),num(r.net.returns),money(r.net.agiUsd)]))}`;}
function districtSources(id){const records=districtEvidence(id),sourceIds=new Set(records.flatMap(r=>r.sourceIds||[])),relevant=sources.filter(s=>sourceIds.has(s.id)||s.districts==='all'||(Array.isArray(s.districts)?s.districts.includes(id):String(s.districts||'').split(',').map(Number).includes(id)));return `<div class="section-heading"><h3>District source registry</h3></div><div class="card-grid two">${sourceCard({title:'2026 NYS BOE unofficial returns',sourceUrl:E[id].sourceUrl,publisher:'NYS Board of Elections',publishedAt:'Updated 21 Nov 2026',verificationStatus:'Official collection · retrieved 22 Nov 2026'})}${sourceCard({title:'Official Senate geography',sourceUrl:D.geometry.metadata.districtSource,publisher:'New York State GIS Program',verificationStatus:'Official polygon geometry'})}${sourceCard({title:'ACS 2024 five-year district tables',sourceUrl:C[id]?.metrics[0]?.officialSourceUrl,publisher:'US Census Bureau',publishedAt:'2020–2024 survey period',verificationStatus:'38 tables freshly retrieved 23 Nov 2026'})}${relevant.map(sourceCard).join('')}</div>`;}
function sourceCard(s){return `<article class="research-card"><span class="eyebrow">${esc(s.id||s.sourceType||'PRIMARY SOURCE')}</span><h3>${esc(s.title||s.name||'Source record')}</h3><p>${esc(s.publisher||'')}</p><p class="meta-line">${esc(s.publishedAt||s.dataVintage||s.sourceDate||'Source date not recorded')}${s.retrievedAt?' · retrieved '+esc(s.retrievedAt):''}</p><p class="muted">${esc(s.verificationStatus||s.status||s.evidenceType||'Source recorded in research collection')}</p><div class="source-links">${link(s.sourceUrl||s.url,'Open source')}</div></article>`;}
function sourcesWorkspace(){return heading('Source registry','THE EVIDENCE UNDER THE INTERFACE','Source dates, collection methods and the complete v5 plan remain accessible inside the terminal.')+`<div class="workspace-body"><div class="tab-strip"><button data-source-tab="registry" class="${state.sourceTab==='registry'?'active':''}">Source registry</button><button data-source-tab="methods" class="${state.sourceTab==='methods'?'active':''}">Collection & limitations</button><button data-source-tab="plan" class="${state.sourceTab==='plan'?'active':''}">Master Plan v5 · 98 pages</button></div>${state.sourceTab==='registry'?`<div class="workspace-toolbar"><input id="sourceSearch" type="search" placeholder="Search sources, publishers or topics" value="${esc(state.search)}"><span class="context-chip">${sources.length} source records</span></div><div class="card-grid" id="sourceCards">${sourceCards()}</div>`:state.sourceTab==='plan'?planReader():methodsContent()}</div>`;}
function sourceCards(){return sources.filter(s=>JSON.stringify(s).toLowerCase().includes(state.search.toLowerCase())).map(sourceCard).join('')||'<p class="empty-search">No matching source.</p>';}
function methodsContent(){return `<div class="card-grid two"><article class="research-card"><h3>Elections</h3><p>63 general-election districts and 112 printed-ballot candidates. 2026 returns are unofficial, updated 21 November. Historical 2024 and collected primary results are certified records. Cross-endorsed ballot lines are aggregated by candidate. Blank and void ballots are excluded from valid-vote shares.</p><p>Westchester emergency ballots were not fully included in the source snapshot. SD35 and SD37 display vote totals with zero reporting EDs; the terminal does not invent a reporting percentage.</p>${link(D.elections.meta.sourceUrl,'NYS BOE')}</article><article class="research-card"><h3>Campaign finance</h3>${(D.finance.meta.methodology||[]).map(x=>`<p>${esc(x)}</p>`).join('')}<p>103 of 112 candidates have a collected donation total. Missing is not zero. Public matching funds, loans, transfers and non-donation receipts are excluded; refunds are not netted.</p>${link(D.finance.meta.sourceUrl,'Official disclosure dataset')}</article><article class="research-card"><h3>Census estimates</h3>${(D.census.meta.notes||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${link(D.census.meta.sourceUrl,'Census release')}${link(D.census.meta.methodologyUrl,'MOE methodology')}</article><article class="research-card"><h3>Geography</h3><p>63 statewide Senate polygons from NYS GIS, matching the 2022 plan. NYC detail uses matching official 26c Senate, neighborhood and election-district geography. All 4,214 NYC election districts and 262 NTAs are represented. SD34 and SD36 detail views show only their NYC portion; the statewide atlas retains their entire districts.</p><p>Geography overlays contain no precinct election returns. Neighborhood intersections are not whole-neighborhood population assignments.</p>${link(D.geometry.metadata.districtSource,'NYS GIS')}${link('https://www.nyc.gov/content/planning/pages/resources/datasets/election-districts','NYC election district data')}</article><article class="research-card"><h3>Issue and legislative evidence</h3><p>${esc(D.issueEvidence.meta.methodology)}</p><p>Imported v5 research is dated 20 November and remains distinguished from freshly retrieved official records. Bills can be introduced, passed by one chamber or enacted; these statuses are never collapsed. Votes stay attached to the named member serving at the time.</p></article><article class="research-card"><h3>Migration</h3>${(D.migrationFresh?.metadata?.limits||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${(D.migrationFresh?.sources||[]).slice(-3).map(s=>link(s.url,s.title)).join('')}</article></div>`;}
function planReader(){const p=D.handoff.pages.find(x=>x.page===state.pdfPage)||D.handoff.pages[0];return `<div class="workspace-toolbar"><button class="outline small" data-page-step="-1" ${p.page<=1?'disabled':''}>← Previous</button><label>Page <select id="pdfPage">${D.handoff.pages.map(x=>`<option value="${x.page}" ${x.page===p.page?'selected':''}>${x.page} / ${D.handoff.pages.length}</option>`).join('')}</select></label><button class="outline small" data-page-step="1" ${p.page>=D.handoff.pages.length?'disabled':''}>Next →</button><span class="context-chip">Original plan · 20 Nov 2026</span></div><article class="research-card reader-content"><h3>Master Plan v5 · page ${p.page}</h3><pre>${esc(p.text)}</pre></article><details class="research-card"><summary>Structured section index (${D.handoff.sections.length})</summary>${D.handoff.sections.map(s=>`<details><summary>${esc(s.title)}</summary>${s.blocks.map(b=>b.type==='table'?structuredTable(b):b.type==='heading'?`<h3>${esc(b.text)}</h3>`:`<p>${esc(b.text)}</p>`).join('')}</details>`).join('')}</details>`;}
function alertsWorkspace(){return heading('Collection & change log','DATED EVENTS · NO SIMULATED LIVE FEED','A transparent account of what was retrieved, what changed and what needs attention.')+`<div class="workspace-body"><div class="record-timeline"><article class="research-card"><time>23 NOV 2026</time><h3>Official evidence collection expanded</h3><p>38 Census tables across all 63 districts; 16 legislative bills; 13 roll-call events; 63 member profiles; detailed NYC geography and six migration vintages.</p><div class="source-links"><button data-nav="people">Census →</button><button data-nav="legislature">Legislature →</button><button data-nav="migration">Migration →</button></div></article><article class="research-card"><time>22 NOV 2026</time><h3>Finance collection assembled</h3><p>103 of 112 candidates have verified donation totals. The remaining nine retain explicit gaps. Committee mapping and exclusions are visible in the finance view.</p><button class="outline" data-nav="money">Inspect finance →</button></article><article class="research-card"><time>21 NOV 2026 · BOE UPDATE</time><h3>Unofficial election snapshot</h3><p>The source still labels 2026 results unofficial. Closest collected contest: SD43, Lander leading Ashby by 340 votes. Full certification has not been imported.</p><button class="outline" data-open-district="43">Inspect SD43 →</button></article><article class="research-card"><time>20 NOV 2026 · HANDOFF SNAPSHOT</time><h3>Master Plan v5 research imported</h3><p>98 pages, 24 layer definitions, 20 issue tracks, 17 migration/property figures and source catalogs. Imported records retain their original verification status.</p><button class="outline" data-nav="sources">Read the source plan →</button></article></div><div class="note-banner">This build is a collected research snapshot. It has no unattended scraping schedule, automatic change detection service or live news stream.</div></div>`;}
function exportsWorkspace(){return heading('Export desk','TAKE THE EVIDENCE WITH YOU','Create a district brief or export a structured record. Downloads stay in this page and use ordinary file links.')+`<div class="workspace-body"><div class="workspace-toolbar">${selectDistrictControl()}</div><div class="card-grid"><article class="research-card"><span class="eyebrow">PDF DOSSIER</span><h3>SD ${state.district} · district brief</h3><p>Election history, candidates, disclosed donors, issue evidence, Census estimates, legislative records and sources in a readable, paginated document.</p><button class="primary" data-export-district="${state.district}">↓ Download district PDF</button></article><article class="research-card"><span class="eyebrow">STRUCTURED DATA</span><h3>District evidence package</h3><p>Download the selected district’s JSON record with original source URLs, collection dates, methodology and margins of error.</p><button class="outline" data-export-json="1">↓ Download district JSON</button></article><article class="research-card"><span class="eyebrow">COMPARISON TABLE</span><h3>SD ${state.compareA} × SD ${state.compareB}</h3><p>A CSV with comparable election, finance and demographic metrics, source periods and Census margins of error.</p><button class="outline" data-export-comparison="1">↓ Download comparison CSV</button></article></div><div class="inline-detail" id="downloadStatus" aria-live="polite">Choose an export. A direct download link will appear here as well.</div></div>`;}
function setRoute(route,{id,tab,issue}={}){const aliases={elections:'districts'};state.route=aliases[route]||route;if(id&&E[id])state.district=Number(id);if(tab)state.tab=tab;if(issue)state.issue=Number(issue);state.search='';render();updateHash(false);}
function updateHash(replace=true){const hash=`#${state.route}?sd=${state.district}${state.route==='dossier'?'&tab='+state.tab:''}${state.route==='issues'?'&issue='+state.issue+'&district='+state.filterDistrict:''}`;if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash);}
function readHash(){const [route,q]=location.hash.slice(1).split('?'),p=new URLSearchParams(q||'');if(route&&[...mainNav,...moreNav].some(x=>x[0]===route)||route==='dossier')state.route=route;let id=+p.get('sd');if(E[id])state.district=id;if(dossierTabs.some(x=>x[0]===p.get('tab')))state.tab=p.get('tab');if(issues.some(x=>+x.id===+p.get('issue')))state.issue=+p.get('issue');if(+p.get('district')>=0&&+p.get('district')<=63)state.filterDistrict=+p.get('district');}
function render(){renderEpoch++;atlas?.dispose();atlas=null;activeCleanup.forEach(f=>f());activeCleanup=[];$('#mainNav').innerHTML=navHTML(mainNav);$('#moreNav').innerHTML=navHTML(moreNav);workspace.scrollTop=0;const routes={home,atlas:home,districts:districtGrid,dossier,candidates:candidateWorkspace,issues:issueWorkspace,compare:compareWorkspace,money:moneyWorkspace,people:peopleWorkspace,legislature:legislatureWorkspace,media:mediaWorkspace,migration:migrationWorkspace,layers:layersWorkspace,sources:sourcesWorkspace,alerts:alertsWorkspace,exports:exportsWorkspace};try{workspace.innerHTML=(routes[state.route]||home)();document.body.classList.toggle('motion-off',!state.motion);bindImages();if(state.route==='home'||state.route==='atlas')initAtlas();}catch(error){console.error('Workspace render',error);workspace.innerHTML=heading('Workspace could not be displayed','RECORD RETAINED','Return to the Command Center or choose another research view.',`<button class="primary" data-nav="home">Command Center</button>`)+`<div class="research-card">${esc(error.message)}</div>`;}document.title=`${state.route==='home'?'The Sixty-Three':state.route==='dossier'?'SD '+state.district+' dossier':state.route[0].toUpperCase()+state.route.slice(1)} | New York Senate Intelligence`;}
function bindImages(){$$('img').forEach(img=>{img.onerror=()=>{const av=img.closest('.avatar');if(av){av.innerHTML=`<span>${esc(initials(img.alt))}</span>`;av.title='Portrait unavailable; open the official profile';}else{img.alt='Source figure unavailable';}};});}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
let downloadURLs=[];function downloadBlob(blob,name){const url=URL.createObjectURL(blob);downloadURLs.push(url);const a=document.createElement('a');a.href=url;a.download=name;a.textContent='Download '+name;a.className='direct-download';a.style.display='none';document.body.appendChild(a);a.click();a.remove();const status=$('#downloadStatus');if(status){status.innerHTML=`<b>Your file is ready.</b><p><a href="${url}" download="${esc(name)}">Download ${esc(name)}</a></p>`;}toast('Your '+name+' download is ready.');}
async function exportDistrict(id){try{toast('Preparing the sourced district brief…');const {createDistrictPDF}=await import('./export.js');const pdf=createDistrictPDF(D,Number(id));downloadBlob(pdf.output('blob'),`The_Sixty_Three_SD${String(id).padStart(2,'0')}_2026-11-23.pdf`);}catch(e){console.error('PDF export',e);toast('The PDF could not be created. Use the JSON export while the record remains available.');}}
function exportJSON(){let id=state.district;const data={generatedAt:D.meta.builtAt,district:id,election:E[id],finance:F[id],census:C[id],geography:G[id],directory:DIR[id],issueEvidence:districtEvidence(id),profile:profileFor(id),sourceMethods:{elections:D.elections.meta,finance:D.finance.meta,census:D.census.meta}};downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`NY_Senate_SD${id}_evidence.json`);}
function comparisonCSV(){const ids=[state.compareA,state.compareB],rows=[['measure','district_a','value_a','moe90_a','district_b','value_b','moe90_b','period','source']];for(const x of C[ids[0]]?.metrics||[]){const y=metrics(ids[1])[x.key];rows.push([x.label,ids[0],x.value,x.moe,ids[1],y?.value,y?.moe,x.period,x.sourceUrl]);}rows.push(['Leader margin points',ids[0],E[ids[0]].leadPercentagePoints,'',ids[1],E[ids[1]].leadPercentagePoints,'','2026 unofficial · BOE21Nov',E[ids[0]].sourceUrl]);rows.push(['2026 leading candidate',ids[0],E[ids[0]].leadingCandidate,'',ids[1],E[ids[1]].leadingCandidate,'','2026 unofficial · BOE21Nov',E[ids[0]].sourceUrl]);rows.push(['2024 certified winner',ids[0],E[ids[0]].history2024?.winner,'',ids[1],E[ids[1]].history2024?.winner,'','2024 certified',E[ids[0]].history2024?.sourceUrl]);rows.push(['Gross disclosed donations USD',ids[0],F[ids[0]]?.totalContributions,'',ids[1],F[ids[1]]?.totalContributions,'','1 Jan 2025–22 Nov 2026; refunds not netted',D.finance.meta.sourceUrl]);rows.push(['Covered finance candidates',ids[0],F[ids[0]]?.coveredCandidates,'',ids[1],F[ids[1]]?.coveredCandidates,'','Collection coverage; missing is not zero',D.finance.meta.sourceUrl]);const csv=rows.map(row=>row.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),`NY_SD${ids[0]}_SD${ids[1]}_comparison.csv`);}
function toggleSearch(){const el=$('#commandSearch');el.hidden=!el.hidden;if(!el.hidden){$('#commandInput').focus();searchCommands($('#commandInput').value);}}
function searchCommands(q){q=q.trim().toLowerCase();let suggestions=[];const comparison=q.match(/^compare\s+(\d{1,2})\s+(\d{1,2})/);if(comparison&&E[+comparison[1]]&&E[+comparison[2]])suggestions.push(`<button data-command-compare="${comparison[1]},${comparison[2]}">Compare SD ${comparison[1]} and SD ${comparison[2]} →</button>`);const sd=q.match(/^(?:sd|district|money)?\s*(\d{1,2})$/);if(sd&&E[+sd[1]])suggestions.push(`<button data-open-district="${+sd[1]}" data-command-result="1">Open SD ${+sd[1]} · ${esc(region(+sd[1]))} →</button>`);if(q.length>1){suggestions.push(...Object.values(E).filter(e=>`${e.candidates.map(x=>x.name).join(' ')} ${region(e.district)}`.toLowerCase().includes(q)).slice(0,5).map(e=>`<button data-open-district="${e.district}" data-command-result="1">SD ${e.district} · ${esc(e.leadingCandidate)} <small>${esc(short(region(e.district),38))}</small> →</button>`));suggestions.push(...issues.filter(i=>i.title.toLowerCase().includes(q)).slice(0,5).map(i=>`<button data-issue="${i.id}" data-command-result="1">Issue ${i.id} · ${esc(i.title)} →</button>`));}if(!q)suggestions=['<span>Districts 1–63 · candidate names · issue titles · compare 38 39</span>'];$('#commandSuggestions').innerHTML=suggestions.join('')||'<span>No matching record. Try a district number, a surname or an issue.</span>';}
document.addEventListener('click',event=>{const el=event.target.closest('button,a[data-nav],g[data-open-district],path[data-map-district]');if(!el)return;const a=el.dataset;if(a.commandResult||a.commandCompare)$('#commandSearch').hidden=true;if(a.nav){setRoute(a.nav);return;}if(a.openDistrict){setRoute('dossier',{id:+a.openDistrict,tab:'overview'});return;}if(a.openDossier){setRoute('dossier',{tab:a.tab||'overview'});return;}if(a.district){updateSelection(+a.district);return;}if(a.mapDistrict){if(state.route==='issues'){state.filterCandidate='all';state.filterDistrict=+a.mapDistrict;state.district=+a.mapDistrict;render();updateHash();}else updateSelection(+a.mapDistrict);return;}if(a.candidate){setRoute('candidates',{id:+a.id});return;}if(a.tab){state.tab=a.tab;render();updateHash();return;}if(a.issue){state.filterCandidate='all';state.issue=+a.issue;state.filterDistrict=+(a.issueDistrict||0);setRoute('issues');return;}if(a.selectIssue){state.filterCandidate='all';state.issue=+a.selectIssue;render();updateHash();return;}if(a.mapMode){setMapMode(a.mapMode);return;}if(a.mapAction){const action=a.mapAction;if(action==='in')atlas?.zoom(1.25);if(action==='out')atlas?.zoom(.8);if(action==='rotate')atlas?.rotate();if(action==='reset'){atlas?.reset();$('#mapSvg')?.setAttribute('viewBox','0 0 1000 780');}if(['nyc','longIsland'].includes(action)){let b=D.geometry.insets[action].viewBox;atlas?.focus(b);$('#mapSvg')?.setAttribute('viewBox',b.join(' '));}if(state.mode==='2D'&&['in','out'].includes(action)){let svg=$('#mapSvg'),b=svg.getAttribute('viewBox').split(' ').map(Number),f=action==='in'?.8:1.25;svg.setAttribute('viewBox',`${b[0]+b[2]*(1-f)/2} ${b[1]+b[3]*(1-f)/2} ${b[2]*f} ${b[3]*f}`);}return;}if(a.geo){state.geo=a.geo;render();return;}if(a.sort){districtSort=a.sort;$('#districtGrid').innerHTML=districtTiles();return;}if(a.financeView){state.financeView=a.financeView;render();return;}if(a.peopleTab){state.peopleTab=a.peopleTab;render();return;}if(a.migrationTab){state.migrationTab=a.migrationTab;render();return;}if(a.sourceTab){state.sourceTab=a.sourceTab;state.search='';render();return;}if(a.pageStep){state.pdfPage=Math.min(98,Math.max(1,state.pdfPage+Number(a.pageStep)));render();return;}if(a.layer){const id=+a.layer;state.layer=id;if(id===12){render();return;}if([5,6,20,21].includes(id))state.peopleTab='institutions';else state.peopleTab='census';if(id===16)state.peopleGroup='household_workers';if(id===19)state.peopleGroup='ancestry';if(id===17)state.mediaPlatform='Reddit';else state.mediaPlatform='all';if(id===15)state.sourceTab='plan';setRoute(layerRoutes[id]||'sources');return;}if(a.exportDistrict){exportDistrict(+a.exportDistrict);return;}if(a.exportJson){exportJSON();return;}if(a.exportComparison){comparisonCSV();return;}if(a.commandCompare){[state.compareA,state.compareB]=a.commandCompare.split(',').map(Number);setRoute('compare');return;}});
document.addEventListener('change',event=>{const el=event.target;switch(el.id){case'districtSelect':state.district=+el.value;render();updateHash();break;case'heatSelect':state.heat=el.value;atlas?.setColors(heatColor);$$('.senate-shape').forEach(p=>p.setAttribute('fill',heatColor(+p.dataset.mapDistrict)));$('#heatNote').textContent=heatNote();$('#mapIssue').hidden=state.heat!=='issues';break;case'mapIssue':state.issue=+el.value;atlas?.setColors(heatColor);$$('.senate-shape').forEach(p=>p.setAttribute('fill',heatColor(+p.dataset.mapDistrict)));break;case'issueDistrict':state.filterDistrict=+el.value;state.filterCandidate='all';render();updateHash();break;case'evidenceFilter':state.filterEvidence=el.value;render();break;case'issueCandidate':state.filterCandidate=el.value;render();break;case'peopleGroup':state.peopleGroup=el.value;render();break;case'legislatureDistrict':case'mediaDistrict':state.filterDistrict=+el.value;render();break;case'mediaPlatform':state.mediaPlatform=el.value;render();break;case'compareA':state.compareA=+el.value;render();break;case'compareB':state.compareB=+el.value;render();break;case'pdfPage':state.pdfPage=+el.value;render();break;}});
document.addEventListener('input',event=>{if(event.target.id==='districtSearch'){state.search=event.target.value;$('#districtGrid').innerHTML=districtTiles();}if(event.target.id==='sourceSearch'){state.search=event.target.value;$('#sourceCards').innerHTML=sourceCards();}if(event.target.id==='commandInput')searchCommands(event.target.value);});
$('#searchToggle').addEventListener('click',toggleSearch);$('#commandClose').addEventListener('click',()=>$('#commandSearch').hidden=true);$('#motionToggle').addEventListener('click',()=>{state.motion=!state.motion;render();toast(state.motion?'Interface motion enabled.':'Interface motion reduced.');});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();toggleSearch();}if(event.key==='Escape'){$('#commandSearch').hidden=true;}if(event.key==='Enter'&&event.target.id==='commandInput'){$('#commandSuggestions button')?.click();}if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-map-district],g[data-open-district]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
window.addEventListener('popstate',()=>{readHash();render();});window.addEventListener('hashchange',()=>{readHash();render();});
window.addEventListener('pagehide',()=>downloadURLs.forEach(u=>URL.revokeObjectURL(u)));
readHash();render();updateHash();
